import {questions} from './content.js?v=12';
import {shuffle,createSession,answerQuiz,advanceSession,skipQuestion,goBack,goForward,resumeQuestion,finishSession,examScore,isReviewing,reviewEntry,convertSessionWording,cleanState} from './engine.js?v=12';
import {enter,disclose,replaceRegion,syncSelections,finishMotion,motionEnabled} from './motion.js?v=12';
import {attachCardGestures} from './gestures.js?v=12';
const KEY='klar-recht-v1',byId=new Map(questions.map(q=>[q.id,q]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',topics:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',cards:'<rect x="5" y="6" width="15" height="15" rx="3"/><path d="M16 3H6a3 3 0 0 0-3 3v10M9 11h7M9 15h5"/>',quiz:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',progress:'<path d="M3 12a9 9 0 1 0 9-9M12 3v9h9"/><path d="m5 4 3 3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="m14 6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',bookmark:'<path d="M7 3h10a1 1 0 0 1 1 1v17l-6-4-6 4V4a1 1 0 0 1 1-1Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.6a5 5 0 0 0-7 0L12 6.4l-1.8-1.8a5 5 0 0 0-7 7L12 20l8.8-8.4a5 5 0 0 0 0-7Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',scale:'<path d="M12 3v18M5 21h14M4 7l8-2 8 2M4 7l-3 7h6L4 7ZM20 7l-3 7h6l-3-7ZM1 14c0 3 6 3 6 0m10 0c0 3 6 3 6 0"/>',ecard:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 14h4m4 0h4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',chevron:'<path d="m8 5 7 7-7 7"/>',skip:'<path d="m5 5 9 7-9 7V5Zm13 0v14"/>',book:'<path d="M12 6c-3-3-7-3-10-2v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2Zm0 0v15"/>'};
const svg=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[{id:'recht',title:'Recht & Verantwortung',short:'Rechtsfragen',caption:'Deine 20 fotografierten Prüfungsfragen.',icon:'scale',color:'#7890dd',bg:'#edf1ff',topics:['grundlagen','taetigkeiten','aufsicht','haftung','vertretung']},{id:'tafel',title:'Tafelfragen & Abrechnung',short:'Neue Tafelfragen',caption:'Deine 30 ausgewählten Fragen mit markierten Belegen.',icon:'book',color:'#bf9565',bg:'#faf2e8',topics:['tafel-form','tafel-sv','tafel-honorar']},{id:'sv',title:'Sozialversicherung',short:'Sozialversicherung',caption:'Prinzipien, Träger, Beiträge & Leistungen.',icon:'shield',color:'#77a398',bg:'#eef6f3',topics:['prinzipien','traeger','beitraege','leistungen','versorgung']},{id:'admin',title:'Ordinationsalltag',short:'Ordinationsalltag',caption:'e-card, Rezepte & wichtige Formulare.',icon:'ecard',color:'#b596c8',bg:'#f5eff9',topics:['ecard','formulare']}];
const topicNames={'tafel-form':'Praxis & Formulare','tafel-sv':'Sozialversicherung · Tafel','tafel-honorar':'Leistungen & Honorarpositionen',grundlagen:'Gesetz & Berufsbild',taetigkeiten:'Erlaubte Tätigkeiten',aufsicht:'Anordnung & Aufsicht',haftung:'Haftung & Regress',vertretung:'Vertretung & Fortbildung',prinzipien:'Grundprinzipien',traeger:'Die Versicherungsträger',beitraege:'Beiträge & Umlagen',leistungen:'Leistungen & Pension',versorgung:'Zahnbehandlung & Versorgung',ecard:'e-card & Admin-Karte',formulare:'Rezepte & Formulare'};
const navItems=[['home','Übersicht','home'],['topics','Themen','topics'],['cards','Karteikarten','cards'],['quiz','Quiz','quiz'],['progress','Fortschritt','progress']];
const main=document.querySelector('main'),modal=document.querySelector('#modal');
let state,storageOK=true;
try {state=cleanState(JSON.parse(localStorage.getItem(KEY)||'null'),byId.keys());}catch{state=cleanState(null,byId.keys());}
convertSessionWording(state.session,!state.simpleLanguage,questions);
const originalFor=q=>!state.simpleLanguage&&!!q.originalChoices;
const questionText=(q,original=originalFor(q))=>original&&q.originalChoices?q.originalQuestion:q.question;
const answerText=(q,original=originalFor(q))=>original&&q.originalChoices?q.originalChoices[q.originalCorrect]:q.answer;
let wordingConfirmation=0,previewIndex=0;
const visibleGroups=()=>groups.filter(g=>state.extendedQuestions||!['sv','admin'].includes(g.id));
const visibleQuestions=()=>questions.filter(q=>state.extendedQuestions||!['sv','admin'].includes(groupFor(q).id));
const visibleKnown=()=>visibleQuestions().filter(q=>state.known.includes(q.id)).length;
const roundVisible=()=>state.session?.ids.every(id=>visibleQuestions().some(q=>q.id===id));
const questionLabel=q=>q.sourceNumber?'Tafelfrage '+q.sourceNumber:'Frage '+q.number;
let reveal=false,activeMode=null,filterGroup='all',filterStatus='all',search='',busy=false;
const expandedCards=new Set(),scrollPositions=new Map();
let currentRoute='',routeScroll=0,cancelCardGesture=()=>{};
const hasActiveRound=()=>state.session&&!state.session.ended&&state.session.queue.length>0&&roundVisible();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;toast('Der Browser kann den Lernstand gerade nicht speichern. Bitte als Datei sichern.');}}
function applyPreferences(){let dark=state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.motion=state.motion?'on':'off';if(!motionEnabled())finishMotion();}
applyPreferences();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyPreferences);
function toast(msg){const e=document.querySelector('.toast');e.textContent=msg;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),4000);}
function groupFor(q){return groups.find(g=>g.topics.includes(q.topic));}
function groupQuestions(g){return questions.filter(q=>g.topics.includes(q.topic));}
function tone(g){return `--tone:${g.color};--tone-bg:${g.bg}`;}
function pct(ids){return Math.round(ids.filter(id=>state.known.includes(id)).length/Math.max(1,ids.length)*100);}
function progress(ids,g){const known=ids.filter(id=>state.known.includes(id)).length;return `<div class="progress-track" role="progressbar" aria-label="${esc(g.title)} gelernt" aria-valuemin="0" aria-valuemax="${ids.length}" aria-valuenow="${known}" style="${tone(g)}"><div class="progress-fill" style="width:${pct(ids)}%"></div></div><div class="progress-label"><span>${known} von ${ids.length} gelernt</span><span>${pct(ids)} %</span></div>`;}
function actionButton(action,label,cls='primary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}${svg('arrow')}</button>`;}
function routeInfo(){const [page,arg]=location.hash.slice(1).split('/');return {page:navItems.some(n=>n[0]===page)||page==='topic'?page:'home',arg};}
function navigate(page){if(location.hash!==`#${page}`)location.hash=page;}
function updateNav(page){
 for(const nav of document.querySelectorAll('.side-nav,.bottom-nav')){
  if(!nav.querySelector('a'))nav.innerHTML=navItems.map(([id,label,icon])=>`<a href="#${id}" data-page="${id}">${svg(icon)}<span>${label}</span></a>`).join('');
  for(const link of nav.querySelectorAll('a')){const selected=link.dataset.page===page;link.classList.toggle('active',selected);if(selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}
 }
 document.querySelector('#page-name').textContent=page==='topic'?'Themen':navItems.find(n=>n[0]===page)?.[1]||'Übersicht';
 syncSelections();
}
function render({animated=true}={}){
 cancelCardGesture();busy=false;const {page,arg}=routeInfo();updateNav(page==='topic'?'topics':page);activeMode=null;
 let content;if((page==='quiz'||page==='cards')&&state.session?.mode===page&&roundVisible()){activeMode=page;content=renderSession();}
 else content=page==='home'?home():page==='topics'?topics():page==='topic'?topicDetail(arg):page==='progress'?progressPage():setup(page);
 main.innerHTML=`<div class="view" data-route="${esc(page)}">${content}</div>`;
 document.body.dataset.study=activeMode||'';
 syncSelections(main,false);updateSetupCount();
 if(animated)enter(main.firstElementChild,{y:8,duration:240});
 if(state.session?.mode==='quiz'&&state.session.answer!==null&&page==='quiz')main.querySelector('[data-action="next"]')?.focus({preventScroll:true});
}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-card behind"></div><div class="art-card"><span class="art-label">EIN THEMA. EIN SCHRITT.</span>${svg('scale','scale-art')}<strong>Alles wird klar.</strong><div class="art-line"></div><div class="art-line short"></div></div><div class="floating-note"><span>✓</span><div><strong>Ein bisschen sicherer.</strong><small>Mit jeder richtigen Antwort.</small></div></div></div>`;}
function home(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en',{timeZone:'Europe/Vienna',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));const days=Math.max(0,Math.ceil((Date.UTC(2026,10,4)-Date.UTC(parts.year,parts.month-1,parts.day))/86400000));const known=visibleKnown();
 return `<div class="greeting"><p><strong>Schön, dass du da bist.</strong> Zeit für einen kleinen Fortschritt.</p><span class="days-label">${days?`Noch ${days} Tage`:'Test · 4. November'}</span></div>
 <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> DEIN TEST AM 4. NOVEMBER</div><h1>Ein gutes Gefühl.<br>Für deinen Test.</h1><p>Recht verstehen. Einfach üben.<br>Ein Thema nach dem anderen –<br>bis du dir sicher bist.</p>${actionButton('quick-start',hasActiveRound()?'Weiterlernen':'Jetzt loslegen')}</div>${heroArt()}</section>
 ${hasActiveRound()?resumeBanner():''}
 <div class="action-grid"><button class="action-card" data-action="go-cards"><span class="action-icon">${svg('cards')}</span><div><h3>Erst verstehen.</h3><p>Kurze Karteikarten.<br>Einfach erklärt, gut gemerkt.</p></div><span class="arrow-circle">${svg('arrow')}</span></button><button class="action-card" data-action="go-quiz"><span class="action-icon lilac">${svg('quiz')}</span><div><h3>Dann sicher werden.</h3><p>Wähle die richtige Antwort.<br>Wiederhole, bis alles sitzt.</p></div><span class="arrow-circle">${svg('arrow')}</span></button></div>
 <div class="section-heading"><div><h2>Dein Lernstoff</h2><p>Dein Prüfungsstoff. Klar voneinander getrennt.</p></div><button class="text-button" data-action="go-topics">Alle Themen ${svg('arrow')}</button></div><div class="topic-grid">${visibleGroups().map(groupCard).join('')}</div>
 <div class="encouragement">${svg('spark')}<span><strong>Du musst nicht alles auf einmal können.</strong> Ein paar Minuten zählen auch.</span><span>${known} / ${visibleQuestions().length} gelernt</span></div>`;
}
function groupCard(g){const ids=groupQuestions(g).map(q=>q.id);return `<button class="topic-card" data-action="group" data-id="${g.id}" style="${tone(g)}"><div class="topic-top"><span class="topic-icon">${svg(g.icon)}</span><small>${ids.length} Karten</small></div><h3>${g.title}</h3><p>${g.caption}</p><div class="topic-progress">${progress(ids,g)}</div></button>`;}
function resumeBanner(){const s=state.session;return `<div class="resume-banner"><p><strong>Deine Runde wartet auf dich.</strong><br>${s.kind==='exam'?'Prüfungsrunde':s.mode==='quiz'?'Quiz':'Karteikarten'} · ${s.done.length} von ${s.ids.length} geschafft · ${s.queue.length} noch offen</p>${actionButton('resume','Fortsetzen')}</div>`;}
function topics(){return `<div class="intro-block"><div class="eyebrow">Dein Lernstoff</div><h1 class="page-title">Alles hat seinen Platz.</h1><p class="intro">Lerne einen Bereich in Ruhe. Wenn du bereit bist, kannst du die Themen im Quiz kombinieren.</p></div><div class="topic-grid">${visibleGroups().map(groupCard).join('')}</div><section class="library-section" aria-labelledby="library-title"><div class="library-heading"><div><div class="eyebrow">Zum Nachschlagen & Verstehen</div><h2 id="library-title">Deine Karten. In aller Ruhe.</h2><p>Tippe auf eine Frage, um die Antwort aufzuklappen.</p></div><span class="library-emblem" aria-hidden="true">${svg('cards')}</span></div>${libraryControls()}<div id="library-results" class="motion-region"><div class="region-content">${library()}</div></div></section>`;}
function libraryControls(){return `<div class="library-toolbar"><div class="filter-row"><label class="search">${svg('search')}<input id="search" type="search" placeholder="Frage oder Begriff suchen" aria-label="Karten durchsuchen" value="${esc(search)}"></label><div class="select-wrap"><select id="group-filter" aria-label="Lernbereich"><option value="all">Alle Bereiche</option>${visibleGroups().map(g=>`<option value="${g.id}" ${filterGroup===g.id?'selected':''}>${g.short}</option>`).join('')}</select>${svg('chevron')}</div></div><div class="segmented library-segments" role="group" aria-label="Kartenfilter">${[['all','Alle'],['bookmarks','Gemerkt'],['mistakes','Fehler'],['new','Noch offen']].map(([id,name])=>`<button data-action="status-filter" data-id="${id}" class="${filterStatus===id?'active':''}" aria-pressed="${filterStatus===id}">${name}</button>`).join('')}</div></div>`;}
function libraryQuestions(){return visibleQuestions().filter(q=>(filterGroup==='all'||groupFor(q).id===filterGroup)&&(questionLabel(q)+' '+questionText(q)+' '+answerText(q)+' '+q.note).toLocaleLowerCase('de').includes(search.toLocaleLowerCase('de'))&&(filterStatus==='all'||filterStatus==='bookmarks'&&state.bookmarks.includes(q.id)||filterStatus==='mistakes'&&state.stats[q.id]?.lastWrong||filterStatus==='new'&&!state.known.includes(q.id)));}
function library(){const qs=libraryQuestions();return `<div class="library-count" role="status"><strong>${qs.length} ${qs.length===1?'Karte':'Karten'}</strong><span>${filterStatus==='bookmarks'?'Deine Merkliste':filterStatus==='mistakes'?'Zuletzt falsch beantwortet':filterStatus==='new'?'Noch nicht als gelernt markiert':'Ein Gedanke nach dem anderen'}</span></div>${qs.length?`<div class="card-list library-list">${qs.map(q=>listCard(q)).join('')}</div>`:`<div class="empty"><span class="empty-icon">${svg(filterStatus==='bookmarks'?'bookmark':'search')}</span><h3>${filterStatus==='bookmarks'?'Hier ist Platz für deine Merkliste.':filterStatus==='mistakes'?'Gerade keine Fehler offen.':'Keine passenden Karten.'}</h3><p>${filterStatus==='bookmarks'?'Tippe auf das Lesezeichen einer Karte. Du findest sie dann hier.':'Probiere einen anderen Filter oder Suchbegriff.'}</p></div>`}`;}
function updateLibrary({animated=true}={}){
 const results=document.querySelector('#library-results');if(!results)return;
 for(const button of main.querySelectorAll('[data-action="status-filter"]')){button.classList.toggle('active',button.dataset.id===filterStatus);button.setAttribute('aria-pressed',String(button.dataset.id===filterStatus));}
 syncSelections(main);
 replaceRegion(results,library(),{animated});
}
function listCard(q){const g=groupFor(q),open=expandedCards.has(q.id),marked=state.bookmarks.includes(q.id),known=state.known.includes(q.id);return `<article class="list-card ${open?'expanded':''}" data-card-id="${q.id}" style="${tone(g)}"><div class="list-card-top"><div class="list-meta"><span class="topic-dot"></span>${esc(topicNames[q.topic])}<span class="question-id">| ${questionLabel(q)}</span>${known?`<span class="learned-tag">${svg('check')} Gelernt</span>`:''}</div><button class="icon-button library-bookmark ${marked?'on':''}" data-action="bookmark" data-id="${q.id}" aria-label="Karte ${marked?'nicht mehr merken':'merken'}" aria-pressed="${marked}">${svg('bookmark')}</button></div><h3 class="list-question"><button class="list-toggle" data-action="expand-card" data-id="${q.id}" aria-expanded="${open}" aria-controls="answer-${q.id}"><span>${esc(questionText(q))}</span><span class="expand-icon">${svg('chevron')}</span></button></h3><div class="list-panel" id="answer-${q.id}" ${open?'':'hidden'}><div class="list-body"><div class="answer-label">Antwort</div><p class="list-answer">${esc(answerText(q))}</p>${q.note?`<div class="note">${esc(q.note)}</div>`:''}<div class="list-source">${svg('book')}<span>${esc(q.source)}</span></div>${sourceEvidence(q)}</div></div></article>`;}
function toggleLibraryCard(button){const id=button.dataset.id,card=button.closest('.list-card'),open=!expandedCards.has(id);if(open)expandedCards.add(id);else expandedCards.delete(id);button.setAttribute('aria-expanded',String(open));card.classList.toggle('expanded',open);disclose(card.querySelector('.list-panel'),open);}
function topicDetail(id){const g=visibleGroups().find(g=>g.id===id),subgroup=visibleGroups().find(g=>g.topics.includes(id));if(!g&&!subgroup)return topics();if(g?.id==='tafel')return tafelDetail(g);const parent=g||subgroup,qs=g?groupQuestions(g):questions.filter(q=>q.topic===id),title=g?g.title:topicNames[id];return `<button class="text-button" data-action="go-topics">${svg('back')} Alle Themen</button><div class="topic-detail-header" style="${tone(parent)}"><span class="topic-icon">${svg(parent.icon)}</span><div><h1>${title}</h1><p>${qs.length} Karten · ${g?g.caption:parent.title}</p></div></div><div class="action-grid"><button class="action-card" data-action="start-topic-cards" data-id="${id}"><span class="action-icon">${svg('cards')}</span><div><h3>Mit Karten lernen</h3><p>Verstehen und selbst beantworten.</p></div><span class="arrow-circle">${svg('arrow')}</span></button><button class="action-card" data-action="start-topic-quiz" data-id="${id}"><span class="action-icon lilac">${svg('quiz')}</span><div><h3>Im Quiz üben</h3><p>Bis jede Frage richtig beantwortet ist.</p></div><span class="arrow-circle">${svg('arrow')}</span></button></div>${g?`<div class="section-heading"><h2>Die kleinen Lernportionen</h2></div><div class="subtopics">${g.topics.map(t=>`<button class="subtopic" data-action="subtopic" data-id="${t}"><div><h3>${topicNames[t]}</h3><p>${questions.filter(q=>q.topic===t).length} Karten</p></div><span class="arrow-circle">${svg('arrow')}</span></button>`).join('')}</div>`:''}<div class="section-heading"><h2>${g?'Karten dieses Bereichs':'Fragen & Antworten'}</h2></div><div class="card-list">${qs.map(listCard).join('')}</div>`;}
function sourceEvidence(q){return q.sourceImage?`<figure class="source-evidence"><figcaption>${svg('book')}<span>Markierter Beleg · Skriptseite ${esc(q.scriptPage)}${q.originalSourceNumber?` · Foto-Nr. ${q.originalSourceNumber}`:''}</span></figcaption><button class="source-image-button" data-action="open-source" data-id="${q.id}" aria-label="Markierten Beleg zu ${esc(questionLabel(q))} vergrößern"><img src="${q.sourceImage}" width="${q.sourceWidth}" height="${q.sourceHeight}" alt="Dein markierter Skriptausschnitt zu ${esc(questionLabel(q))}" loading="lazy" decoding="async"><span>Beleg vergrößern ${svg('arrow')}</span></button></figure>`:'';}
function previewCard(){const q=questions.filter(q=>q.sourceNumber)[previewIndex];return `<article class="preview-card" data-preview-id="${q.id}"><div class="preview-toolbar"><span class="eyebrow">VORSCHAU · ${previewIndex+1} / 30</span><div class="preview-navigation"><button class="icon-button" data-action="preview-prev" aria-label="Vorherige Vorschau" ${previewIndex===0?'disabled':''}>${svg('back')}</button><button class="icon-button" data-action="preview-next" aria-label="Nächste Vorschau" ${previewIndex===29?'disabled':''}>${svg('arrow')}</button></div></div><span class="preview-number">${questionLabel(q)} · ${esc(topicNames[q.topic])}</span><h2>${esc(q.question)}</h2><div class="preview-answer"><div class="answer-label">Kurzantwort</div><p>${esc(q.answer)}</p></div>${q.note?`<div class="note">${esc(q.note)}</div>`:''}<p class="source">${esc(q.source)}</p>${sourceEvidence(q)}</article>`;}
function tafelDetail(g){return `<button class="text-button" data-action="go-topics">${svg('back')} Alle Themen</button><div class="topic-detail-header" style="${tone(g)}"><span class="topic-icon">${svg(g.icon)}</span><div><h1>${g.title}</h1><p>30 Fragen · Genau deine nummerierte Auswahl</p></div></div><div id="preview-stage" class="motion-region"><div class="region-content">${previewCard()}</div></div><div class="preview-start-actions"><button class="secondary" data-action="start-topic-cards" data-id="tafel">${svg('cards')} Kartenrunde starten</button><button class="primary" data-action="start-topic-quiz" data-id="tafel">Im Quiz üben ${svg('arrow')}</button></div><details class="preview-all"><summary>Alle 30 Fragen durchsehen ${svg('chevron')}</summary><div class="card-list">${groupQuestions(g).map(listCard).join('')}</div></details>`;}
function setup(mode){
 const quiz=mode==='quiz';
 return `<div class="intro-block"><div class="eyebrow">${quiz?'Wissen anwenden':'Verstehen & merken'}</div><h1 class="page-title">${quiz?'Zeig dir, was du kannst.':'Eine Karte. Ein klarer Gedanke.'}</h1><p class="intro">${quiz?'Übe in Ruhe oder starte eine Prüfungsrunde mit einem Ergebnis in Prozent. Nach jeder Antwort siehst du sofort, ob sie richtig ist.':'Beantworte die Frage zuerst im Kopf. Decke dann die Antwort auf. Bewerte mit den Buttons oder wische die Karte zur Seite.'}</p></div>${hasActiveRound()?resumeBanner():''}
 <form id="setup-form" class="setup-panel">${quiz?`<div class="quiz-kind segmented" role="radiogroup" aria-label="Quizmodus"><label class="active"><input type="radio" name="quiz-kind" value="practice" checked><span>${svg('spark')}Üben</span></label><label><input type="radio" name="quiz-kind" value="exam"><span>${svg('quiz')}Prüfungsrunde</span></label></div><p id="quiz-description" class="mode-description">Fehler kommen später wieder, bis du jede Frage richtig beantwortet hast.</p>`:''}
 <h2>Was möchtest du lernen?</h2><p>Wähle einen oder mehrere Bereiche. Du bestimmst die Größe deiner Runde.</p><div class="choice-topics">${visibleGroups().map((g,i)=>`<label class="choice-topic"><input type="checkbox" name="group" value="${g.id}" ${i===0?'checked':''}><span><strong>${g.title}</strong><small>${groupQuestions(g).length} Karten · ${g.id==='recht'?'aus deinen Fotos':g.id==='tafel'?'deine aktuelle Auswahl':g.id==='sv'?'Tafel & Skript':'zweites Tafelfoto'}</small></span></label>`).join('')}</div><fieldset class="order-field"><legend>Reihenfolge</legend><div class="round-order quiz-kind segmented" role="radiogroup" aria-label="Fragenreihenfolge">${[['sorted','Nach Nummer'],['mixed','Gemischt']].map(([value,label])=>`<label class="${state.roundOrder===value?'active':''}"><input type="radio" name="round-order" value="${value}" ${state.roundOrder===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><div class="setup-options"><label class="switch-label"><input type="checkbox" name="open"> Nur noch offene Fragen</label><label class="switch-label"><input type="checkbox" name="bookmarks"> Nur gemerkte Karten</label></div><p class="source" id="setup-count"></p><button type="submit" class="primary">${quiz?'Quiz starten':'Kartenrunde starten'} ${svg('arrow')}</button></form><div class="encouragement">${svg('heart')}<span>Kein Zeitdruck. ${quiz?'In der Prüfung zählt die erste Antwort pro Frage.':'„Kann ich“ zählt als gelernt; „Noch einmal“ bleibt in der Runde.'}</span></div>`;
}
function updateSetupCount(){
 const form=main.querySelector('#setup-form');if(!form)return;
 const data=new FormData(form),selected=data.getAll('group');
 const count=visibleQuestions().filter(q=>selected.includes(groupFor(q).id)&&(!data.has('open')||!state.known.includes(q.id))&&(!data.has('bookmarks')||state.bookmarks.includes(q.id))).length;
 form.querySelector('#setup-count').textContent=count?`${count} ${count===1?'Karte':'Karten'} in deiner Runde.`:'Keine passenden Karten. Ändere die Auswahl oder die Filter.';
 const submit=form.querySelector('[type="submit"]');submit.disabled=!count;
 if(data.has('quiz-kind')){
  const exam=data.get('quiz-kind')==='exam';

  form.querySelector('#quiz-description').textContent=exam?'Ein Durchlauf. Die erste Antwort zählt. Richtig oder falsch siehst du sofort; am Ende bekommst du dein Ergebnis in Prozent.':'Fehler kommen später wieder, bis du jede Frage richtig beantwortet hast.';
  submit.innerHTML=`${exam?'Prüfungsrunde starten':'Quiz starten'} ${svg('arrow')}`;
 }
 for(const label of form.querySelectorAll('.quiz-kind label'))label.classList.toggle('active',label.querySelector('input').checked);
 syncSelections(form);
}
function startRound(ids,mode,original=!state.simpleLanguage,kind='practice',ordering=state.roundOrder){
 if(!ids.length){toast('Keine passenden Karten. Ändere die Auswahl oder die Filter.');return;}
 if(state.session&&!state.session.ended&&state.session.queue.length){
  showModal(`<h2>Neue Runde starten?</h2><p>Deine aktuelle Runde wird ersetzt. Dein bereits gespeicherter Lernstand bleibt erhalten.</p><div class="data-actions"><button class="secondary" data-action="close-modal">Zurück</button><button class="primary" id="confirm-new">Neue Runde starten</button></div>`);
  document.querySelector('#confirm-new').onclick=()=>{modal.close();launch(ids,mode,original,kind,ordering);};
 }else launch(ids,mode,original,kind,ordering);
}
function launch(ids,mode,original,kind='practice',ordering=state.roundOrder){
 ids=ids.filter(id=>visibleQuestions().some(q=>q.id===id));if(!ids.length)return;
 original=!state.simpleLanguage;
 state.roundOrder=ordering==='sorted'?'sorted':'mixed';
 state.session=createSession([...ids].sort((a,b)=>byId.get(a).number-byId.get(b).number),mode,original,kind,state.roundOrder);reveal=false;save();
 if(location.hash===`#${mode}`)render();else navigate(mode);
 window.scrollTo({top:0,behavior:'instant'});
}
function sessionCaption(s){
 if(isReviewing(s))return `Rückblick<span>Schritt ${s.reviewIndex+1} von ${s.history.length} · Wertung bleibt</span>`;
 if(s.kind==='exam'){const score=examScore(s);return s.ended||!s.queue.length?`Prüfung abgeschlossen<span>${score.total-score.open} von ${score.total} beantwortet</span>`:`Prüfung · ${score.total-score.open} von ${score.total} beantwortet<span>${score.open} noch offen · Ergebnis am Ende</span>`;}
 return `${s.done.length} von ${s.ids.length} ${s.mode==='quiz'?'richtig':'geschafft'}<span>${s.queue.length} noch offen${s.errors?` · ${s.errors} ${s.errors===1?'Wiederholung':'Wiederholungen'}`:''}</span>`;
}
function progressCount(s){return s.kind==='exam'?examScore(s).total-examScore(s).open:s.done.length;}
function renderSession(){
 const s=state.session,finished=s.ended||!s.queue.length;
 return `<div class="study-wrap"><div class="study-top"><div class="study-top-actions"><button class="text-button" data-action="${finished?'finish-home':'pause-round'}">${svg('back')}${finished?'Zur Übersicht':'Pausieren'}</button>${!finished?`<button class="text-button end-round" data-action="end-round">${svg('close')}Beenden</button>`:''}</div><div class="session-caption">${sessionCaption(s)}</div></div><div class="study-progress" role="progressbar" aria-label="${s.kind==='exam'?'Prüfungsfragen beantwortet':'Runde geschafft'}" aria-valuenow="${progressCount(s)}" aria-valuemin="0" aria-valuemax="${s.ids.length}"><span style="width:${Math.round(progressCount(s)/s.ids.length*100)}%"></span></div><div id="study-stage" class="motion-region"><div class="region-content">${studyContent()}</div></div><p class="study-help" ${(finished&&!isReviewing(s))?'hidden':''}>${s.mode==='cards'?'Antwort aufklappen · Wischen oder mit der Maus ziehen<span>←: noch einmal · →: kann ich · S: überspringen · B: zurück</span>':'Tasten 1–4: Antwort wählen · Enter: weiter · S: überspringen · B: zurück'}<span>${storageOK?'Deine Runde wird auf diesem Gerät gespeichert.':'Speichern ist gerade nicht möglich. Sichere deinen Lernstand als Datei.'}</span></p></div>`;
}
function flashAnswer(q,original){return `<div class="flash-answer-body"><div class="answer-label">Antwort</div><p class="answer-text">${esc(answerText(q,original))}</p>${q.note?`<div class="note">${esc(q.note)}</div>`:''}<div class="list-source">${svg('book')}<span>${esc(q.source)}</span></div>${sourceEvidence(q)}</div>`;}
function quizFeedback(q,answer,review=false){
 const right=answer.answer==='correct',exam=state.session.kind==='exam';
 return `<div class="quiz-feedback ${right?'':'incorrect'}" role="status"><h3>${right?'Richtig. Ein Schritt weiter.':exam?'Noch nicht richtig. Hier ist die Erklärung.':'Noch nicht ganz. Du bekommst eine neue Chance.'}</h3><p>${esc(answerText(q,state.session.original))}</p>${q.note?`<div class="note">${esc(q.note)}</div>`:''}<p class="source" style="margin-top:12px">${esc(q.source)}</p>${review?'<p class="feedback-hint">Deine damalige Wertung bleibt erhalten.</p>':exam?'<p class="feedback-hint">Diese erste Antwort zählt für dein Ergebnis.</p>':!right?'<p class="feedback-hint">Diese Frage kommt später wieder.</p>':''}</div>`;
}
function roundNavigation(s){
 const review=isReviewing(s),backDisabled=!s.history.length||review&&s.reviewIndex===0;
 const hint=review?'Ansehen, ohne neu zu werten':s.mode==='quiz'?'Übersprungene Fragen bleiben offen.':'';
 return `<div class="round-nav"><button class="round-nav-button" data-action="round-back" ${backDisabled?'disabled':''}>${svg('back')}Zurück</button>${hint?`<span>${hint}</span>`:''}${review?`<button class="round-nav-button" data-action="review-next">Weiter${svg('arrow')}</button>`:`<button class="round-nav-button" data-action="skip-question" ${(s.queue.length<2||s.answer!==null)?'disabled':''}>Überspringen${svg('skip')}</button>`}</div>`;
}
function reviewControls(s,entry){
 const q=byId.get(entry.id),status=entry.answer==='skipped'?`Übersprungen · ${s.queue.includes(q.id)?'noch offen':'inzwischen beantwortet'}`:s.mode==='cards'?(entry.answer==='correct'?'Als „Kann ich“ bewertet':'Für „Noch einmal“ vorgemerkt'):(entry.answer==='correct'?'Richtig beantwortet':'Falsch beantwortet');
 const canResume=!s.ended&&s.answer===null&&s.queue.includes(q.id)&&!(s.kind==='exam'&&s.results[q.id]);
 return `<div class="review-controls"><p>${svg(entry.answer==='skipped'?'skip':entry.answer==='correct'?'check':'book')}<span>${status}</span></p><div>${canResume?`<button class="secondary" data-action="review-resume" data-id="${q.id}">${s.mode==='cards'?'Diese Karte jetzt lernen':'Diese Frage jetzt beantworten'}</button>`:''}<button class="text-button" data-action="review-current">${s.ended||!s.queue.length?'Zum Ergebnis':s.mode==='cards'?'Zur aktuellen Karte':'Zur aktuellen Frage'}${svg('arrow')}</button></div></div>`;
}
function studyContent(){
 const s=state.session,entry=reviewEntry(s),review=!!entry;
 if(!entry&&(s.ended||!s.queue.length))return completed(s);
 const q=byId.get(entry?.id||s.queue[0]),g=groupFor(q),cards=s.mode==='cards';
 const original=s.original&&q.originalChoices,options=original?q.originalChoices:q.choices,correct=original?q.originalCorrect:q.correct;
 if(!cards&&!review&&!s.choiceOrder){s.choiceOrder=shuffle([0,1,2,3]);save();}
 const answer=review?{answer:entry.answer==='skipped'?null:entry.answer,selected:entry.selected,choiceOrder:entry.choiceOrder||[0,1,2,3]}:s;
 const question=original?q.originalQuestion:q.question;
 const card=`<article class="study-card ${cards?'flash-card':''} ${reveal?'is-revealed':''} ${review?'is-review':''}" data-question-id="${q.id}" style="${tone(g)}"><div class="study-card-top"><span class="pill"><span>${esc(topicNames[q.topic])}</span><span class="question-id">| ${questionLabel(q)}</span></span><button class="icon-button bookmark ${state.bookmarks.includes(q.id)?'on':''}" data-action="bookmark" data-id="${q.id}" aria-label="Karte ${state.bookmarks.includes(q.id)?'nicht mehr merken':'merken'}" aria-pressed="${state.bookmarks.includes(q.id)}">${svg('bookmark')}</button></div>${cards?`
 <span class="swipe-intent swipe-intent-known" aria-hidden="true">${svg('check')}Kann ich</span><span class="swipe-intent swipe-intent-again" aria-hidden="true">${svg('back')}Noch einmal</span><div class="flash-front"><div class="question-number">${q.id.startsWith('recht')?'FOTOFRAGE · ':''}${review?'DEIN RÜCKBLICK':'DENK ERST SELBST NACH'}</div><h1 class="study-question"><button class="flash-toggle" data-action="toggle-flash" aria-expanded="${reveal}" aria-controls="flash-answer">${esc(question)}</button></h1><button class="reveal-button" data-action="toggle-flash" aria-expanded="${reveal}" aria-controls="flash-answer"><span>${reveal?'Antwort zuklappen':'Tippen, um die Antwort aufzuklappen'}</span>${svg('chevron')}</button></div><div id="flash-answer" ${reveal?'':'hidden'}>${flashAnswer(q,original)}</div>`:`
 <div class="question-number">${q.id.startsWith('recht')?'FOTOFRAGE · ':''}${review?'DEIN RÜCKBLICK':s.kind==='exam'?'PRÜFUNGSRUNDE':original?'PRÜFUNGSWORTLAUT':'WÄHLE EINE ANTWORT'}</div><h1 class="study-question">${esc(question)}</h1><div class="quiz-options">${answer.choiceOrder.map((idx,pos)=>`<button class="quiz-option ${answer.answer!==null?(idx===correct?'correct':idx===answer.selected?'wrong':'dim'):''}" data-action="answer" data-index="${idx}" ${(review||answer.answer!==null)?'disabled':''}><span class="option-letter">${answer.answer!==null&&idx===correct?svg('check'):answer.answer!==null&&idx===answer.selected?svg('close'):String.fromCharCode(65+pos)}</span><span>${esc(options[idx])}</span></button>`).join('')}</div><div id="feedback-panel" ${answer.answer!==null?'':'hidden'}>${answer.answer!==null?quizFeedback(q,answer,review):''}</div>`}</article>`;
 return `${card}${review?reviewControls(s,entry):cards?`
 <div class="rating-actions"><button class="again" data-action="rate-again" ${reveal?'':'disabled'}>${svg('back')}Noch einmal</button><button class="known" data-action="rate-known" ${reveal?'':'disabled'}>Kann ich ${svg('check')}</button></div><p class="gesture-hint" ${reveal?'':'hidden'}>${reveal?'Nach links: Noch einmal · Nach rechts: Kann ich':''}</p>`:`<div class="quiz-next" ${s.answer!==null?'':'hidden'}>${actionButton('next',s.queue.length===1&&(s.kind==='exam'||s.answer==='correct')?'Ergebnis ansehen':'Weiter')}</div>`}${roundNavigation(s)}`;
}
function updateSessionChrome(){
 const s=state.session;
 main.querySelector('.session-caption').innerHTML=sessionCaption(s);
 const progress=main.querySelector('.study-progress');progress.setAttribute('aria-valuenow',progressCount(s));progress.firstElementChild.style.width=`${Math.round(progressCount(s)/s.ids.length*100)}%`;
 const help=main.querySelector('.study-help');if(help)help.hidden=(s.ended||!s.queue.length)&&!isReviewing(s);
 const actions=main.querySelector('.study-top-actions');if(actions&&(s.ended||!s.queue.length))actions.innerHTML=`<button class="text-button" data-action="finish-home">${svg('back')}Zur Übersicht</button>`;
}
function updateStudy(direction=1){
 cancelCardGesture();if(!main.querySelector('#study-stage')){render();return;}
 updateSessionChrome();replaceRegion(main.querySelector('#study-stage'),studyContent(),{direction});busy=false;
 const h=main.querySelector('#study-stage > .region-content .study-question,#study-stage > .region-content .completed h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}
 const top=main.querySelector('.study-wrap').getBoundingClientRect().top;if(top<12)window.scrollTo({top:window.scrollY+top-20,behavior:motionEnabled()?'smooth':'instant'});
}
function toggleFlash(){
 if(activeMode!=='cards'||!state.session||(!state.session.queue.length&&!isReviewing(state.session))||(state.session.ended&&!isReviewing(state.session)))return;
 cancelCardGesture();reveal=!reveal;
 const card=main.querySelector('#study-stage > .region-content .study-card');card.classList.toggle('is-revealed',reveal);
 card.querySelectorAll('[data-action="toggle-flash"]').forEach(button=>button.setAttribute('aria-expanded',String(reveal)));
 card.querySelector('.reveal-button span').textContent=reveal?'Antwort zuklappen':'Tippen, um die Antwort aufzuklappen';
 main.querySelectorAll('.rating-actions button').forEach(button=>button.disabled=!reveal);
 const hint=main.querySelector('.gesture-hint');if(hint){hint.hidden=!reveal;hint.textContent=reveal?'Nach links: Noch einmal · Nach rechts: Kann ich':'';}
 disclose(card.querySelector('#flash-answer'),reveal);document.querySelector('#announcement').textContent=reveal?'Antwort aufgedeckt.':'Antwort zugeklappt.';
}
function canRateCard(card){return activeMode==='cards'&&reveal&&state.session&&!state.session.ended&&!isReviewing(state.session)&&!busy&&!modal.open&&card.dataset.questionId===state.session.queue[0];}
function rateCard(right,swiped=false){
 const card=main.querySelector('#study-stage > .region-content .flash-card');if(!card||!canRateCard(card))return;
 busy=true;const s=state.session,q=byId.get(s.queue[0]);record(q,right);s.attempts++;if(!right)s.errors++;
 advanceSession(s,right);reveal=false;save();updateStudy(swiped?0:right?1:-1);
 document.querySelector('#announcement').textContent=right?'Als gelernt markiert.':'Die Karte kommt später wieder.';
}
function showQuizAnswer(){
 const s=state.session,q=byId.get(s.queue[0]),correct=s.original&&q.originalChoices?q.originalCorrect:q.correct;
 for(const button of main.querySelectorAll('#study-stage > .region-content [data-action="answer"]')){const idx=Number(button.dataset.index);button.disabled=true;button.classList.add(idx===correct?'correct':idx===s.selected?'wrong':'dim');if(idx===correct||idx===s.selected)button.querySelector('.option-letter').innerHTML=svg(idx===correct?'check':'close');}
 const feedback=main.querySelector('#feedback-panel');feedback.innerHTML=quizFeedback(q,s);disclose(feedback,true);
 const next=main.querySelector('.quiz-next');next.hidden=false;next.querySelector('button').innerHTML=`${s.queue.length===1&&(s.kind==='exam'||s.answer==='correct')?'Ergebnis ansehen':'Weiter'}${svg('arrow')}`;
 main.querySelector('[data-action="skip-question"]').disabled=true;
 updateSessionChrome();enter(next,{y:4,duration:180});next.querySelector('button').focus({preventScroll:true});
}
function resultsReview(s){
 return `<details class="result-review"><summary>Deine Fragen im Überblick<span>${s.ids.length} Fragen${svg('chevron')}</span></summary><div class="result-questions">${s.ids.map(id=>{const q=byId.get(id),result=s.results[id],status=result?(result.correct?'Richtig':'Falsch'):'Offen',options=s.original&&q.originalChoices?q.originalChoices:q.choices;return `<details class="result-question"><summary><span class="result-dot ${result?result.correct?'right':'wrong':'open'}">${svg(result?result.correct?'check':'close':'skip')}</span><span>${questionLabel(q)} · ${esc(questionText(q,s.original))}</span><small>${status}</small>${svg('chevron')}</summary><div>${result?.selected!==null&&result?.selected!==undefined?`<p class="selected-answer">Deine Antwort: ${esc(options[result.selected])}</p>`:''}<div class="answer-label">Richtige Antwort</div><p>${esc(answerText(q,state.session.original))}</p>${q.note?`<div class="note">${esc(q.note)}</div>`:''}<p class="source">${esc(q.source)}</p></div></details>`;}).join('')}</div></details>`;
}
function completed(s){
 const exam=s.kind==='exam',score=exam?examScore(s):null,partial=s.queue.length>0;
 return `<section class="completed ${exam?'exam-completed':''}">${exam?`<div class="score-ring" style="--score:${score.percent}%" role="img" aria-label="${score.percent} Prozent richtig"><div><strong>${new Intl.NumberFormat('de',{maximumFractionDigits:1}).format(score.percent)}<span>%</span></strong><small>richtig beantwortet</small></div></div>`:`<div class="completed-mark">${svg('check')}</div>`}<div class="eyebrow" style="justify-content:center;margin-bottom:10px">${exam?'Dein Prüfungsergebnis':partial?'Für heute geschafft':'Runde geschafft'}</div><h1>${exam?'Jetzt weißt du, wo du stehst.':partial?'Runde beendet.':'Das sitzt jetzt.'}</h1><p>${exam?`${score.correct} von ${score.total} Fragen richtig. Die erste Antwort zählt.${score.open?`<br>${score.open} offene ${score.open===1?'Frage zählt':'Fragen zählen'} mit 0 Punkten.`:''}`:partial?`Du hast ${s.done.length} von ${s.ids.length} ${s.mode==='quiz'?'Fragen richtig beantwortet':'Karten als gelernt markiert'}.<br>Dein Lernstand bleibt gespeichert.`:`Du hast alle ${s.ids.length} ${s.mode==='quiz'?'Fragen richtig beantwortet':'Karten als „Kann ich“ markiert'}.<br>Auch die, die zwischendurch noch schwer waren.`}</p><div class="result-stats">${exam?`<div class="result-right"><strong>${score.correct}</strong><small>Richtig</small></div><div class="result-wrong"><strong>${score.wrong}</strong><small>Falsch</small></div><div><strong>${score.open}</strong><small>Offen</small></div>`:`<div><strong>${s.done.length}</strong><small>${s.mode==='quiz'?'richtig beantwortet':'Karten gelernt'}</small></div><div><strong>${s.attempts}</strong><small>Antworten insgesamt</small></div><div><strong>${s.errors}</strong><small>Wiederholungen</small></div>`}</div><div class="result-actions">${actionButton('finish-home','Zur Übersicht')}<button class="secondary" data-action="restart">${exam?'Prüfung wiederholen':'Noch einmal üben'}</button></div>${s.history.length?`<button class="text-button result-back" data-action="round-back">${svg('back')}Zur letzten ${s.mode==='cards'?'Karte':'Frage'}</button>`:''}${exam?resultsReview(s):'<p class="source" style="margin-top:18px">Wiederhole die Themen an einem anderen Tag, damit sie länger bleiben.</p>'}</section>`;
}
function record(q,right){state.stats[q.id]||={correct:0,wrong:0,lastWrong:false};state.stats[q.id][right?'correct':'wrong']++;state.stats[q.id].lastWrong=!right;if(right&&!state.known.includes(q.id))state.known.push(q.id);if(!right)state.known=state.known.filter(id=>id!==q.id);}
function next(){const s=state.session;if(!s||s.mode!=='quiz'||s.ended||isReviewing(s)||s.answer===null)return;const right=s.answer==='correct';advanceSession(s,right);save();reveal=false;updateStudy(right?1:-1);}
function backInRound(){const s=state.session;if(!s||!goBack(s))return;reveal=s.mode==='cards'&&reviewEntry(s).answer!=='skipped';save();updateStudy(-1);}
function forwardInReview(){const s=state.session;if(!s||!goForward(s))return;reveal=s.mode==='cards'&&!!reviewEntry(s)&&reviewEntry(s).answer!=='skipped';save();updateStudy(1);}
function askEndRound(){
 const s=state.session;if(!s||s.ended)return;
 const score=s.kind==='exam'?examScore(s):null;
 showModal(`<h2>${score?'Prüfungsrunde beenden?':'Runde beenden?'}</h2><p style="margin-top:14px">${score?`${score.total-score.open} von ${score.total} Fragen sind beantwortet. Du bekommst jetzt dein Ergebnis; ${score.open} offene Fragen zählen mit 0 Punkten.`:'Deine bisher gelernten Karten und Antworten bleiben gespeichert. Die laufende Runde wird abgeschlossen.'}</p><div class="data-actions"><button class="secondary" data-action="close-modal">Weiterlernen</button><button class="primary" data-action="confirm-end">${score?'Prüfung auswerten':'Runde beenden'}</button></div>`);
}

function progressPage(){const misses=visibleQuestions().filter(q=>state.stats[q.id]?.lastWrong);const attempts=visibleQuestions().reduce((n,q)=>n+(state.stats[q.id]?.correct||0)+(state.stats[q.id]?.wrong||0),0);return `<div class="intro-block"><div class="eyebrow">Dein Fortschritt</div><h1 class="page-title">Jeder Schritt zählt.</h1><p class="intro">„Gelernt“ heißt: zuletzt im Quiz richtig beantwortet oder auf der Karte als „Kann ich“ markiert. Ein neuer Fehler macht die Frage wieder offen.</p></div><div class="stat-grid"><div class="stat-card"><strong>${visibleKnown()}<span style="font-size:16px;color:var(--muted)"> / ${visibleQuestions().length}</span></strong><p>Karten gelernt</p></div><div class="stat-card"><strong>${misses.length}</strong><p>Zuletzt noch unsicher</p></div><div class="stat-card"><strong>${attempts}</strong><p>Antworten insgesamt</p></div></div>${visibleGroups().map(g=>`<div class="progress-topic" style="${tone(g)}"><span class="topic-icon">${svg(g.icon)}</span><div><h3>${g.title}</h3>${progress(groupQuestions(g).map(q=>q.id),g)}</div><button class="text-button" data-action="group" data-id="${g.id}">Zum Bereich ${svg('arrow')}</button></div>`).join('')}${misses.length?`<div class="section-heading"><div><h2>Hier lohnt sich eine Wiederholung.</h2><p>Diese ${misses.length} Karten waren zuletzt noch unsicher.</p></div></div>${actionButton('retry-mistakes','Unsichere Fragen üben')}<div class="card-list">${misses.map(listCard).join('')}</div>`:`<div class="encouragement">${svg('check')}<span>${attempts?'Gerade sind keine zuletzt falsch beantworteten Karten offen.':'Dein Fortschritt beginnt mit deiner ersten Antwort.'}</span></div>`}<p class="source" style="margin-top:24px">Der Lernstand gehört zu diesem Browser. Unter „Einstellungen“ kannst du ihn sichern und auf einem anderen Gerät importieren. Eine automatische Synchronisierung gibt es nicht.</p>`;}
function showModal(content){delete modal.dataset.source;cancelCardGesture();modal.querySelector('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-header"><span></span><button class="icon-button" data-action="close-modal" aria-label="Schließen">${svg('close')}</button></div>${content}</div>`;if(!modal.open)modal.showModal();syncSelections(modal,false);}
function settings(){wordingConfirmation=0;showModal(`<h2>Einstellungen</h2><p style="margin-top:10px">Dein Lernraum, so wie er sich für dich gut anfühlt.</p><h3>Erscheinungsbild</h3><div class="segmented">${[['system','System'],['light','Hell'],['dark','Dunkel']].map(([id,name])=>`<button data-action="theme" data-id="${id}" class="${state.theme===id?'active':''}" aria-pressed="${state.theme===id}">${name}</button>`).join('')}</div><label class="switch-label" style="margin-top:12px"><input type="checkbox" id="motion-toggle" ${state.motion?'checked':''}> Sanfte Bewegungen</label><p>„Bewegung reduzieren“ auf deinem Gerät wird zusätzlich berücksichtigt.</p><h3>Fragenumfang</h3><label class="switch-label"><input type="checkbox" id="extended-toggle" ${state.extendedQuestions?'checked':''}> Erweiterte Fragen</label><p>Zusätzlich die bisherigen Kategorien Sozialversicherung und Ordinationsalltag anzeigen. Standardmäßig lernst du die 20 Rechtsfragen und die 30 neuen Tafelfragen. Dein gespeicherter Lernstand bleibt erhalten.</p><h3>Lernwortlaut</h3><p>${state.simpleLanguage?'Einfache Version eingeschaltet.':'Prüfungswortlaut ist eingeschaltet.'} Bei den 20 Fotofragen wird genau eine Fassung angezeigt. Die übrigen Fragen bleiben unverändert.</p><div class="data-actions"><button class="secondary" data-action="${state.simpleLanguage?'use-original-wording':'ask-simple-wording'}">${state.simpleLanguage?'Prüfungswortlaut verwenden':'Einfache Version einschalten'}</button></div><h3>Lernstand sichern</h3><p>Hier wird lokal in deinem Browser gespeichert. Exportiere den Stand und importiere die Datei auf deinem iPad, iPhone oder Mac, wenn du das Gerät wechselst.</p><div class="data-actions"><button class="secondary" data-action="export">Lernstand exportieren</button><button class="secondary" data-action="import">Datei importieren</button><input hidden type="file" id="import-file" accept="application/json,.json"></div><h3>Auf den Home-Bildschirm</h3><p>In Safari über „Teilen“ → „Zum Home-Bildschirm“ hinzufügen. Nach dem ersten Online-Aufruf kann die installierte Lernseite auch ohne Internet funktionieren. Der Browser kann gespeicherte Daten bei Bedarf entfernen.</p><h3>Neuanfang</h3><button class="text-button danger" data-action="reset">Gesamten Lernstand zurücksetzen</button>`);}
function changeWording(simple){
 state.simpleLanguage=simple;convertSessionWording(state.session,!simple,questions);save();reveal=false;render({animated:false});settings();
}
function askSimpleWording(){
 wordingConfirmation=1;
 showModal('<h2>Einfache Version einschalten?</h2><p>Die 20 Fotofragen werden dann einfacher formuliert. Du lernst diese Fassung anstelle des Prüfungswortlauts; es werden nie beide Fassungen zusammen gezeigt.</p><div class="data-actions"><button class="secondary" data-action="settings">Abbrechen</button><button class="primary" data-action="confirm-simple-wording">Weiter</button></div>');
}
function sources(){showModal(`<h2>Inhalte & Quellen</h2><p style="margin-top:12px">Standardmäßig siehst du die 20 Rechtsfragen und genau die 30 nummerierten Fragen aus deinen neuen Screenshots. Zu den neuen Fragen gibt es kurze Antworten und die markierten Belege aus deinem SV-Skript von 2024. GV, EV und SV sind nun als Gesamtvertrag, Einzelvertrag und Stellvertretung geklärt. Die bisherigen 49 Zusatzfragen bleiben über „Erweiterte Fragen“ verfügbar. Andere markierte Skriptstellen und reine Tafeleinträge sind nicht als neue Fragen ergänzt.</p><div class="source-box"><h3 style="margin-top:0">Eure Lernunterlagen</h3><p>„Berufsspezifische Rechtsgrundlagen“, vor allem PDF-Seiten 8–14 und 24–27.<br>„Abrechnung mit Sozialversicherung“, PDF-Seiten 3–19 (inklusive handschriftlicher Fragen auf Seite 5).<br>Die Quellenangabe auf jeder Karte nennt die PDF-Seite; bei den neuen Fragen werden die gedruckte Skriptseite und die PDF-Seite in deiner neuen Datei getrennt genannt.</p></div><h3>Offizieller Abgleich</h3><p><a href="https://www.ris.bka.gv.at/Dokumente/BgblAuth/BGBLA_2012_I_38/BGBLA_2012_I_38.pdf" target="_blank" rel="noopener">Zahnärztliche Assistenz-Gesetz 2012</a><br><a href="https://www.ris.bka.gv.at/eli/bgbl/i/2005/126/P73/NOR40135615" target="_blank" rel="noopener">ZÄG § 73: Tätigkeitsbereich & Aufsicht</a><br><a href="https://www.gesundheit.gv.at/lexikon/S/solidaritaetsprinzip-hk.html" target="_blank" rel="noopener">Solidaritätsprinzip</a><br><a href="https://www.sozialversicherung.gv.at/cdscontent/?contentid=10007.870439&portal=oegkportal" target="_blank" rel="noopener">Pflichtversicherung & Träger</a><br><a href="https://www.chipkarte.at/cdscontent/?contentid=10007.678597&portal=ecardportal" target="_blank" rel="noopener">e-card: Sicherheit & Daten</a></p><h3>Wichtige Präzisierungen</h3><p>Die Trägerzuordnung auf Seite 4 des SV-Skripts ist teilweise zu pauschal: Selbständige sind nicht allgemein bei der PVA pensionsversichert; geringfügige Beschäftigung allein begründet grundsätzlich keine Krankenversicherung. Die Karten unterscheiden diese Fälle. Veraltete Eurobeträge und Beitragssätze werden nicht abgefragt.</p><h3>Prüfungswortlaut</h3><p>Die 20 Fotofragen erscheinen standardmäßig in Themen, Karteikarten und Quiz mit ursprünglicher Frage und Antwort. Satzzeichen und offensichtliche Tippfehler sind bereinigt; die rot markierte Lösung ist übernommen. Die einfache Fassung lässt sich in den Einstellungen nach zwei Bestätigungen einschalten. Es erscheint immer nur eine Fassung. Die 30 neuen Tafelfragen sind bewusst kurz formuliert; die Wortlaut-Einstellung verändert diese nicht. Die 49 bisherigen Zusatzfragen bleiben unverändert.</p><h3>Gestaltung</h3><p>Systemschrift und eine Web-Umsetzung mit sanfter Bewegung, angelehnt an <a href="https://developer.apple.com/design/" target="_blank" rel="noopener">Apples Designvorgaben</a>. Die Website verwendet keine nativen SwiftUI-Komponenten.</p>`);}
main.addEventListener('submit',e=>{if(e.target.id!=='setup-form')return;e.preventDefault();const form=new FormData(e.target);const selected=form.getAll('group');const qs=visibleQuestions().filter(q=>selected.includes(groupFor(q).id)&&(!form.has('open')||!state.known.includes(q.id))&&(!form.has('bookmarks')||state.bookmarks.includes(q.id)));startRound(qs.map(q=>q.id),routeInfo().page,!state.simpleLanguage,form.get('quiz-kind'),form.get('round-order'));});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled){if(activeMode==='cards'&&!reveal&&e.target.closest('.flash-card')&&!e.target.closest('button,a,input,select')&&!getSelection().toString())toggleFlash();return;}const {action,id}=b.dataset;
 if(action==='preview-prev'||action==='preview-next'){previewIndex=Math.max(0,Math.min(29,previewIndex+(action==='preview-next'?1:-1)));replaceRegion(main.querySelector('#preview-stage'),previewCard(),{direction:action==='preview-next'?1:-1});const nextFocus=main.querySelector(`#preview-stage > .region-content:not(.motion-ghost) [data-action="${action}"]:not(:disabled)`)||main.querySelector('#preview-stage > .region-content:not(.motion-ghost) .preview-navigation button:not(:disabled)');nextFocus?.focus({preventScroll:true});return;}
 if(action==='open-source'){const q=byId.get(id);if(!q?.sourceImage)return;showModal(`<h2>${esc(questionLabel(q))} · Markierter Beleg</h2><p>${esc(q.source)}</p><a class="text-button source-original" href="${q.sourceImage}" target="_blank" rel="noopener">Bild in voller Größe öffnen ${svg('arrow')}</a><img class="source-full" src="${q.sourceImage}" width="${q.sourceWidth}" height="${q.sourceHeight}" alt="Markierter Skriptausschnitt zu ${esc(q.question)}">`);modal.dataset.source='true';return;}
 if(action==='close-modal'){modal.close();return;}if(action==='settings'){settings();return;}if(action==='sources'){sources();return;}
 if(action.startsWith('go-')){navigate(action.slice(3));return;}if(action==='group'||action==='subtopic'){navigate('topic/'+id);return;}
 if(action==='quick-start'){if(hasActiveRound())navigate(state.session.mode);else navigate('cards');return;}
 if(action==='resume'){navigate(state.session.mode);return;}if(action==='pause-round'){save();navigate('home');return;}
 if(action==='bookmark'){
  const focused=document.activeElement===b;
  const index=[...main.querySelectorAll('.library-bookmark')].indexOf(b);
  state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();
  if(b.classList.contains('icon-button')){b.classList.toggle('on',state.bookmarks.includes(id));b.setAttribute('aria-pressed',state.bookmarks.includes(id));b.setAttribute('aria-label',state.bookmarks.includes(id)?'Karte nicht mehr merken':'Karte merken');}
  else b.textContent=state.bookmarks.includes(id)?'Gemerkt · entfernen':'Für später merken';
  if(filterStatus==='bookmarks'&&document.querySelector('#library-results')){
   updateLibrary();
   if(focused){const buttons=main.querySelectorAll('.library-bookmark');(buttons[Math.min(Math.max(0,index),buttons.length-1)]||main.querySelector('[data-action="status-filter"].active'))?.focus({preventScroll:true});}
  }
  return;
 }
 if(action==='status-filter'){if(filterStatus!==id){filterStatus=id;updateLibrary();}return;}
 if(action==='expand-card'){toggleLibraryCard(b);return;}
 if(action.startsWith('start-topic-')){const qs=visibleGroups().find(g=>g.id===id)?groupQuestions(visibleGroups().find(g=>g.id===id)):visibleQuestions().filter(q=>q.topic===id);startRound(qs.map(q=>q.id),action.endsWith('quiz')?'quiz':'cards');return;}
 if(action==='toggle-flash'){toggleFlash();return;}
 if(action==='round-back'){backInRound();return;}
 if(action==='review-next'){forwardInReview();return;}
 if(action==='review-current'){state.session.reviewIndex=null;reveal=false;save();updateStudy(1);return;}
 if(action==='review-resume'){if(resumeQuestion(state.session,id)){reveal=false;save();updateStudy(-1);}return;}
 if(action==='end-round'){askEndRound();return;}
 if(action==='confirm-end'){finishSession(state.session);reveal=false;save();modal.close();updateStudy(0);return;}
 if(action==='skip-card'||action==='skip-question'){if(!activeMode||!skipQuestion(state.session))return;reveal=false;save();updateStudy(1);document.querySelector('#announcement').textContent='Übersprungen. Bleibt für später in dieser Runde.';return;}
 if(action==='rate-again'||action==='rate-known'){rateCard(action==='rate-known');return;}
 if(action==='answer'){const s=state.session;if(!s||s.mode!=='quiz'||s.ended||isReviewing(s))return;const q=byId.get(s.queue[0]);const idx=Number(b.dataset.index);const correct=s.original&&q.originalChoices?q.originalCorrect:q.correct;if(!answerQuiz(s,q.id,idx===correct,idx))return;s.selected=idx;record(q,idx===correct);save();showQuizAnswer();return;}
 if(action==='next'){next();return;}if(action==='finish-home'){state.session=null;save();navigate('home');return;}
 if(action==='restart'){const s=state.session;launch(s.ids,s.mode,s.original,s.kind,s.ordering);return;}if(action==='retry-mistakes'){startRound(visibleQuestions().filter(q=>state.stats[q.id]?.lastWrong).map(q=>q.id),'quiz');return;}
 if(action==='ask-simple-wording'){askSimpleWording();return;}
 if(action==='confirm-simple-wording'){if(wordingConfirmation!==1)return;wordingConfirmation=2;showModal('<h2>Einfachen Wortlaut verwenden?</h2><p>Damit ersetzt du bei den 20 Fotofragen die Originalfragen und Originalantworten durch die einfache Fassung – in Themen, Karteikarten und Quiz. Du kannst jederzeit zum Prüfungswortlaut zurückwechseln. Dein Lernstand und die Wertungen bleiben erhalten.</p><div class="data-actions"><button class="secondary" data-action="settings">Abbrechen</button><button class="primary" data-action="enable-simple-wording">Einfache Version aktivieren</button></div>');return;}
 if(action==='enable-simple-wording'){if(wordingConfirmation!==2)return;changeWording(true);return;}
 if(action==='use-original-wording'){changeWording(false);return;}
 if(action==='theme'){state.theme=id;applyPreferences();save();for(const button of modal.querySelectorAll('[data-action="theme"]')){button.classList.toggle('active',button.dataset.id===id);button.setAttribute('aria-pressed',String(button.dataset.id===id));}syncSelections(modal);return;}
 if(action==='export'){const blob=new Blob([JSON.stringify({app:'klar-recht',exported:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`klar-lernstand-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Lernstand als Datei gesichert.');return;}
 if(action==='import'){document.querySelector('#import-file').click();return;}
 if(action==='reset'){showModal('<h2>Wirklich von vorne beginnen?</h2><p style="margin-top:14px">Alle Markierungen, Antworten und die laufende Runde werden auf diesem Gerät gelöscht. Sichere deinen Stand vorher, wenn du ihn behalten möchtest.</p><div class="data-actions"><button class="secondary" data-action="settings">Zurück</button><button class="primary" data-action="confirm-reset">Lernstand löschen</button></div>');return;}
 if(action==='confirm-reset'){state=cleanState({theme:state.theme,motion:state.motion},byId.keys());save();modal.close();reveal=false;render();toast('Du startest wieder mit einem leeren Lernstand.');}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;updateLibrary({animated:false});}});
document.addEventListener('change',async e=>{if(e.target.closest('#setup-form'))updateSetupCount();if(e.target.id==='group-filter'){filterGroup=e.target.value;updateLibrary();}if(e.target.id==='extended-toggle'){state.extendedQuestions=e.target.checked;filterGroup='all';save();render({animated:false});return;}if(e.target.id==='motion-toggle'){state.motion=e.target.checked;applyPreferences();save();}
 if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>2_000_000){toast('Die Datei ist zu groß. Bitte eine Klar-Lernstanddatei wählen.');return;}try{const raw=JSON.parse(await file.text());if(raw.app!=='klar-recht'||raw.version!==1||!Array.isArray(raw.known)||!Array.isArray(raw.bookmarks)||!raw.stats||typeof raw.stats!=='object')throw Error();const incoming=cleanState(raw,byId.keys());showModal('<h2>Lernstand übernehmen?</h2><p style="margin-top:14px">Der importierte Stand ersetzt den aktuellen Stand auf diesem Gerät. '+incoming.known.length+' Karten sind darin als gelernt markiert.</p><div class="data-actions"><button class="secondary" data-action="settings">Abbrechen</button><button class="primary" id="confirm-import">Übernehmen</button></div>');document.querySelector('#confirm-import').onclick=()=>{state=incoming;convertSessionWording(state.session,!state.simpleLanguage,questions);save();applyPreferences();modal.close();reveal=false;render();toast('Dein Lernstand wurde übernommen.');};}catch{toast('Diese Datei ist keine gültige Klar-Lernstanddatei.');}}
});
document.addEventListener('keydown',e=>{
 if(modal.open||!state.session||!activeMode||['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY'].includes(document.activeElement.tagName)||e.altKey||e.ctrlKey||e.metaKey)return;
 if(e.key.toLowerCase()==='b'){e.preventDefault();backInRound();return;}
 if(isReviewing(state.session)){if(e.key==='ArrowRight'||e.key==='Enter'){e.preventDefault();forwardInReview();}if(e.key==='ArrowLeft'){e.preventDefault();backInRound();}if(activeMode==='cards'&&e.code==='Space'){e.preventDefault();toggleFlash();}return;}
 if(e.key.toLowerCase()==='s'){e.preventDefault();main.querySelector('[data-action="skip-question"]')?.click();return;}
 if(activeMode==='cards'){if(e.code==='Space'){e.preventDefault();toggleFlash();}if(reveal&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();rateCard(e.key==='ArrowRight');}}
 if(activeMode==='quiz'){if(state.session.answer===null&&['1','2','3','4'].includes(e.key)){e.preventDefault();main.querySelectorAll('#study-stage > .region-content [data-action="answer"]')[Number(e.key)-1]?.click();}if(e.key==='Enter'&&state.session.answer!==null){e.preventDefault();next();}}
});
modal.addEventListener('close',()=>{wordingConfirmation=0;});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(!link||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const route=link.getAttribute('href').slice(1);if(route==='main'){e.preventDefault();main.focus();return;}if(!['home','topics','cards','quiz','progress','topic'].includes(route.split('/')[0]))return;e.preventDefault();navigate(route);});
window.addEventListener('scroll',()=>{routeScroll=window.scrollY;},{passive:true});
window.addEventListener('hashchange',()=>{if(location.hash===currentRoute)return;scrollPositions.set(currentRoute,routeScroll);currentRoute=location.hash;reveal=false;render();window.scrollTo({top:scrollPositions.get(currentRoute)||0,behavior:'instant'});routeScroll=window.scrollY;});
window.addEventListener('storage',e=>{if(e.key===KEY){toast('Der Lernstand wurde in einem anderen Tab geändert. Lade diese Seite neu, bevor du weiterlernst.');}});
cancelCardGesture=attachCardGestures(main,{canRate:canRateCard,onRate:right=>rateCard(right,true)});
currentRoute=location.hash;render({animated:false});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
